export async function archiveAsset(assetId:string,input:{expectedRevision:number;dependencyPreviewId:string;idempotencyKey:string;actor:string;reason:string}):Promise<AssetDetail>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const repeated=(await client.query("SELECT asset_id,action,dependency_preview_id,detail FROM new_design.asset_events WHERE asset_id=$1 AND idempotency_key=$2",[assetId,input.idempotencyKey])).rows[0];if(repeated){if(String(repeated.action)!=="archive"||asText(repeated.dependency_preview_id)!==input.dependencyPreviewId||String(repeated.detail)!==input.reason)throw new NewDesignError("该幂等键已用于不同的资产归档请求。",409);await client.query("COMMIT");return getAsset(assetId);}const asset=assertFound((await client.query("SELECT * FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='asset' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,space_id uuid,book_id uuid,asset_key text,asset_kind text,title text,status text,current_version_id uuid,revision integer,created_by text,created_at timestamptz,updated_at timestamptz,archived_at timestamptz) WHERE record.status='active') asset_record WHERE id=$1 FOR UPDATE",[assetId])).rows[0],"资产不存在。");if(asset.status!=="active"||Number(asset.revision)!==input.expectedRevision||!asset.current_version_id)throw new NewDesignError("资产已归档、无采用版本或修订已变化。",409);const preview=assertFound((await client.query("SELECT * FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='dependency_change_preview' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,book_id uuid,book_change_set_id uuid,old_resource_id uuid,new_resource_id uuid,reason text,impact_snapshot jsonb,snapshot_hash text,idempotency_key text,created_by text,created_at timestamptz,visual_input_hash text,visual_source jsonb) WHERE record.status='active') dependency_change_preview_record WHERE id=$1",[input.dependencyPreviewId])).rows[0],"归档附件前必须先生成影响预览。"),oldResource=await resourceIdForVersion(client,assetId,String(asset.current_version_id));if(String(preview.book_id)!==String(asset.book_id)||String(preview.old_resource_id)!==oldResource||preview.new_resource_id!==null)throw new NewDesignError("附件归档影响预览已经过期。",409);const revision=Number(asset.revision)+1,eventId=randomUUID();await (async()=>{const current=await requireRecordCard(client,String(assetId),"asset","原记录不存在。",{includeArchived:true,lock:true});const row=await replaceRecordCard(client,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"asset",values:{...current,status:"archived",revision:revision,archived_at:new Date().toISOString(),updated_at:new Date().toISOString()}});return{rows:[row],rowCount:1};})();await client.query("INSERT INTO new_design.asset_events(id,asset_id,book_id,asset_version_id,action,from_status,to_status,asset_revision,dependency_preview_id,idempotency_key,actor,detail) VALUES($1,$2,$3,$4,'archive','active','archived',$5,$6,$7,$8,$9)",[eventId,assetId,asset.book_id,asset.current_version_id,revision,input.dependencyPreviewId,input.idempotencyKey,input.actor,input.reason]);await client.query("COMMIT");return getAsset(assetId);}catch(error){await client.query("ROLLBACK");throw error;}finally{client.release();}}

