export async function endAssetMount(id:string,reason:string):Promise<AssetMount>{const pool=await getNewDesignPool(),row=assertFound((await pool.query("UPDATE new_design.asset_links SET status='ended',ended_at=now(),end_reason=$2 WHERE id=$1 AND status='active' RETURNING *",[id,reason])).rows[0],"资产挂载不存在或已经结束。");return mapMount(row);}

